mapper.select:
select a.DATA_STATUS dataStatus, a.INSTITUTION_CODE institutionCode, a.PRD_REGIST_CODE prdRegistCode, a.ACCOUNT_NO accountNo, a.ACCOUNT_NAME accountName, a.TRADE_NO tradeNo, a.TRADE_PS tradePs, a.TRADE_COUNTER_ACC_NO tradeCounterAccNo, a.TRADE_COUNTER_ACC_NAME tradeCounterAccName, a.TRADE_COUNTER_ACC_BANK_NAME tradeCounterAccBankName, a.TRADE_COUNTER_ACC_BANK_NO tradeCounterAccBankNo, a.TRADE_CCY tradeCcy, a.TRADE_AMT tradeAmt, a.TRADE_VDATE tradeVdate, a.TRADE_TIME tradeTime,
a.POSTSCRIPT postscript, a.REMARK remark from CHB_SALER_STL_DEAL_INFO a where 1=1
and a.TRADE_PS = #{tradePs,jdbcType=VARCHAR}
and a.INSTITUTION_CODE = #{institutionCode,jdbcType=VARCHAR}
and a.DATA_STATUS = #{dataStatus,jdbcType=VARCHAR}
and a.PRD_REGIST_CODE like concat(concat('%',#{prdRegistCode,jdbcType=VARCHAR}),'%')
and a.TRADE_NO = #{tradeNo,jdbcType=VARCHAR}
and a.TRADE_VDATE between to_date(#{searchTradeVdateStart,jdbcType=VARCHAR},'yyyy-mm-dd') and to_date(#{searchTradeVdateEnd,jdbcType=VARCHAR},'yyyy-mm-dd')

select count(REGIST_SEQNO) from CHB_SALER_STL_DEAL_INFO
where
PRD_REGIST_CODE=#{prdRegistCode}
and TRADE_NO=#{tradeNo}
